import Modal from '../../components/Modal';
import Token from '../../components/tokens/Token';
import { HAZARD_ENVIRONMENTS } from '../../data/hazards';
import {
  NOTHING_EVENT_ENVIRONMENTS,
  NOTHING_EVENT_TRIGGER_TEXT,
} from '../../data/nothingEvents';
import { BATTLE_ENVIRONMENTS } from '../battle/battleEnvironments';
import { getEnemyById } from '../battle/enemies';
import {
  getDecisionTranslations,
  getEnemyDisplayName,
  getGameplayLanguage,
  getHazardTranslations,
} from '../../i18n/translations';
import DebugPotionGrantControls from './DebugPotionGrantControls';
import { DEBUG_TOKEN_TYPES, getDebugTokenTypeLabel } from './tokenBagAdmin';
import './debug.css';

function DebugModal({
  currentPlayer,
  eliteBossEnemyAssignments = {},
  enemyOptions = [],
  isChooseEventModeEnabled = false,
  isOpen,
  message,
  onEnableAnywhereMode,
  onToggleChooseEventMode = () => {},
  onClose,
  onDiscardPendingPotion,
  onDiscardPendingToken,
  onGivePotion,
  onGiveToken,
  onPendingPotionReplacementChange,
  onStartBattle,
  onStartDecision,
  onStartNothingEvent = () => {},
  onStartRollAgainEvent = () => {},
  onStartRiverMiniGame,
  onStartSelectedEnemyBattle,
  onPendingTokenReplacementChange,
  onReplacePendingPotion,
  onReplacePendingToken,
  onSelectedEnvironmentChange,
  onSelectedDecisionEnvironmentChange,
  onSelectedEnemyIdChange,
  onSelectedHazardEnvironmentChange = () => {},
  onSelectedNothingEnvironmentChange = () => {},
  onSelectedPotionIdChange,
  onSelectedPotionPlayerIdChange,
  onSelectedTokenTypeChange,
  onStartCaveMiniGame,
  onStartHazard = () => {},
  pendingPotionGrant = null,
  players = [],
  selectedEnemyId = '',
  selectedDecisionEnvironment = 'fields',
  selectedEnvironment = 'fields',
  selectedHazardEnvironment = 'field',
  selectedNothingEnvironment = 'field',
  pendingTokenType = '',
  selectedPotionId = '',
  selectedPotionPlayerId = '',
  selectedReplacementPotionIndex = '',
  selectedReplacementTokenId = '',
  selectedTokenType = 'red',
}) {
  const isCurrentPlayerReady = Boolean(currentPlayer?.hasCommittedInitialSpells);
  const isAnywhereModeEnabled = Boolean(currentPlayer?.anywhereMode);
  const isTokenSelectionDisabled = !currentPlayer || !isCurrentPlayerReady || Boolean(pendingTokenType);
  const currentLanguage = getGameplayLanguage(currentPlayer?.language);
  const decisionTranslations = getDecisionTranslations(currentLanguage);
  const hazardTranslations = getHazardTranslations(currentLanguage);
  const decisionLanguageClassName = `language-${currentLanguage}`;
  const chooseEventModeText =
    currentLanguage === 'jp'
      ? isChooseEventModeEnabled
        ? '\u30a4\u30d9\u30f3\u30c8\u9078\u629e\u30e2\u30fc\u30c9\u3092\u7121\u52b9\u306b\u3059\u308b'
        : '\u30a4\u30d9\u30f3\u30c8\u9078\u629e\u30e2\u30fc\u30c9\u3092\u6709\u52b9\u306b\u3059\u308b'
      : isChooseEventModeEnabled
        ? 'Disable choose event mode'
        : 'Enable choose event mode';
  const eliteBossEnemies = eliteBossEnemyAssignments
    ? [
        ['Elite Tower Gravel', eliteBossEnemyAssignments.eliteTowerGravel],
        ['Elite Tower Woods', eliteBossEnemyAssignments.eliteTowerWoods],
        ['Boss Battle', eliteBossEnemyAssignments.bossBattle],
      ]
    : [];

  return (
    <Modal
      actions={
        <button type="button" disabled={Boolean(pendingPotionGrant)} onClick={onClose}>
          Close
        </button>
      }
      ariaLabel="Debug"
      isOpen={isOpen}
      panelClassName="debug-modal-panel"
    >
      <div className="debug-modal-layout">
        <p>Debug</p>
        <p>
          {currentPlayer
            ? `Current player: ${currentPlayer.colour}`
            : 'No current player is available outside gameplay turns.'}
        </p>
        {eliteBossEnemyAssignments ? (
          <div className="debug-elite-boss-enemies">
            <h2>Elite / Boss Enemies</h2>
            {eliteBossEnemies.map(([label, enemyId]) => (
              <div key={label}>
                {`${label}: ${getEnemyDisplayName(
                  currentLanguage,
                  getEnemyById(enemyId)
                )}`}
              </div>
            ))}
          </div>
        ) : null}
        <div className="debug-anywhere-mode-controls">
          <p>Anywhere Mode applies to the current player only.</p>
          <p>{`Anywhere Mode: ${isAnywhereModeEnabled ? 'Enabled' : 'Disabled'}`}</p>
          <button
            type="button"
            disabled={!currentPlayer || isAnywhereModeEnabled}
            onClick={onEnableAnywhereMode}
          >
            Enable Anywhere Mode
          </button>
          <button
            className={decisionLanguageClassName}
            type="button"
            disabled={!currentPlayer}
            onClick={onToggleChooseEventMode}
          >
            {chooseEventModeText}
          </button>
        </div>

        <div className="debug-battle-controls">
          <p>Start a debug battle for the current player.</p>
          <label htmlFor="debug-battle-environment">Battle Environment</label>
          <select
            id="debug-battle-environment"
            value={selectedEnvironment}
            disabled={!currentPlayer}
            onChange={(event) => onSelectedEnvironmentChange(event.target.value)}
          >
            {BATTLE_ENVIRONMENTS.map((environment) => (
              <option key={environment} value={environment}>
                {`${environment.charAt(0).toUpperCase()}${environment.slice(1)}`}
              </option>
            ))}
          </select>
          {[1, 2, 3, 4].map((level) => (
            <button
              key={level}
              type="button"
              disabled={!currentPlayer}
              onClick={() => onStartBattle(level)}
            >
              {`Level ${level}`}
            </button>
          ))}
          <label htmlFor="debug-enemy-select">Enemy</label>
          <select
            id="debug-enemy-select"
            value={selectedEnemyId}
            disabled={!currentPlayer}
            onChange={(event) => onSelectedEnemyIdChange(event.target.value)}
          >
            {enemyOptions.map((enemyOption) => (
              <option key={enemyOption.id} value={enemyOption.id}>
                {enemyOption.label}
              </option>
            ))}
          </select>
          <button
            type="button"
            disabled={!currentPlayer || !selectedEnemyId}
            onClick={onStartSelectedEnemyBattle}
          >
            Start Selected Enemy Battle
          </button>
        </div>

        <div className="debug-hazard-controls">
          <h2 className={decisionLanguageClassName}>
            {hazardTranslations.hazards}
          </h2>
          <label
            className={decisionLanguageClassName}
            htmlFor="debug-hazard-environment"
          >
            {hazardTranslations.environment}
          </label>
          <select
            id="debug-hazard-environment"
            value={selectedHazardEnvironment}
            disabled={!currentPlayer}
            onChange={(event) =>
              onSelectedHazardEnvironmentChange(event.target.value)
            }
          >
            {HAZARD_ENVIRONMENTS.map(({ id, label }) => (
              <option key={id} value={id}>
                {label}
              </option>
            ))}
          </select>
          <button
            className={decisionLanguageClassName}
            type="button"
            disabled={!currentPlayer}
            onClick={onStartHazard}
          >
            {hazardTranslations.triggerHazard}
          </button>
        </div>

        <div className="debug-nothing-event-controls">
          <h2 className={decisionLanguageClassName}>Nothing Event</h2>
          <label
            className={decisionLanguageClassName}
            htmlFor="debug-nothing-event-environment"
          >
            Environment
          </label>
          <select
            id="debug-nothing-event-environment"
            value={selectedNothingEnvironment}
            disabled={!currentPlayer}
            onChange={(event) =>
              onSelectedNothingEnvironmentChange(event.target.value)
            }
          >
            {NOTHING_EVENT_ENVIRONMENTS.map(({ id, label }) => (
              <option key={id} value={id}>
                {label}
              </option>
            ))}
          </select>
          <button
            className={decisionLanguageClassName}
            type="button"
            disabled={!currentPlayer}
            onClick={onStartNothingEvent}
          >
            {NOTHING_EVENT_TRIGGER_TEXT[currentLanguage]}
          </button>
        </div>

        <div className="debug-roll-again-event-controls">
          <h2 className={decisionLanguageClassName}>Roll Again Event</h2>
          <button
            className={decisionLanguageClassName}
            type="button"
            disabled={!isCurrentPlayerReady}
            onClick={onStartRollAgainEvent}
          >
            Trigger Roll Again Event
          </button>
        </div>

        <div className="debug-mini-game-controls">
          <h2>Mini Games</h2>
          <label
            className={decisionLanguageClassName}
            htmlFor="debug-decision-environment"
          >
            {decisionTranslations.environment}
          </label>
          <select
            id="debug-decision-environment"
            value={selectedDecisionEnvironment}
            disabled={!currentPlayer}
            onChange={(event) =>
              onSelectedDecisionEnvironmentChange(event.target.value)
            }
          >
            {BATTLE_ENVIRONMENTS.map((environment) => (
              <option key={environment} value={environment}>
                {`${environment.charAt(0).toUpperCase()}${environment.slice(1)}`}
              </option>
            ))}
          </select>
          <button
            className={decisionLanguageClassName}
            type="button"
            disabled={!currentPlayer}
            onClick={onStartDecision}
          >
            {decisionTranslations.startDecision}
          </button>
          <button type="button" disabled={!currentPlayer} onClick={onStartCaveMiniGame}>
            Start Cave Mini Game
          </button>
          <button type="button" disabled={!currentPlayer} onClick={onStartRiverMiniGame}>
            Start River Mini Game
          </button>
        </div>

        {currentPlayer && !isCurrentPlayerReady ? (
          <p>Finish the current player&apos;s initial spell setup before using debug token tools.</p>
        ) : null}

        <div className="debug-token-give-controls">
          <label htmlFor="debug-token-type">Token type</label>
          <select
            id="debug-token-type"
            value={selectedTokenType}
            disabled={isTokenSelectionDisabled}
            onChange={(event) => onSelectedTokenTypeChange(event.target.value)}
          >
            {DEBUG_TOKEN_TYPES.map((tokenType) => (
              <option key={tokenType} value={tokenType}>
                {getDebugTokenTypeLabel(tokenType, currentPlayer?.language)}
              </option>
            ))}
          </select>

          <button type="button" disabled={isTokenSelectionDisabled} onClick={onGiveToken}>
            Give Token
          </button>
        </div>

        {message ? <p>{message}</p> : null}

        {pendingTokenType ? (
          <div className="debug-token-replacement-flow">
            <p>{`New token: ${getDebugTokenTypeLabel(
              pendingTokenType,
              currentPlayer.language
            )}`}</p>
            <div className="debug-token-choice-list" role="radiogroup" aria-label="Bag tokens to discard">
              {currentPlayer.tokenBag.map((token) => (
                <label key={token.id} className="debug-token-choice">
                  <input
                    checked={selectedReplacementTokenId === token.id}
                    name="debug-token-replacement"
                    type="radio"
                    value={token.id}
                    onChange={(event) => onPendingTokenReplacementChange(event.target.value)}
                  />
                  <Token
                    ariaLabel={`${getDebugTokenTypeLabel(
                      token.type,
                      currentPlayer.language
                    )} token`}
                    language={currentPlayer.language}
                    showName
                    tokenType={token.type}
                  />
                </label>
              ))}
            </div>

            <div className="debug-token-replacement-actions">
              <button type="button" onClick={onDiscardPendingToken}>
                Discard New Token
              </button>
              <button
                type="button"
                disabled={!selectedReplacementTokenId}
                onClick={onReplacePendingToken}
              >
                Replace Selected Token
              </button>
            </div>
          </div>
        ) : null}

        <DebugPotionGrantControls
          onDiscardPendingPotion={onDiscardPendingPotion}
          onGivePotion={onGivePotion}
          onPendingPotionReplacementChange={onPendingPotionReplacementChange}
          onReplacePendingPotion={onReplacePendingPotion}
          onSelectedPotionIdChange={onSelectedPotionIdChange}
          onSelectedPotionPlayerIdChange={onSelectedPotionPlayerIdChange}
          pendingPotionGrant={pendingPotionGrant}
          players={players}
          selectedPotionId={selectedPotionId}
          selectedPotionPlayerId={selectedPotionPlayerId}
          selectedReplacementPotionIndex={selectedReplacementPotionIndex}
        />
      </div>
    </Modal>
  );
}

export default DebugModal;
